gofmt -l internal/api/ && echo "GOFMT-CLEAN"; echo '--- mutation sanity: does raw-digit assertion catch a float-rounded value? ---'; cat > "$HOME/jsonprobe/mut_test.go" <<'EOF'
package main

import (
	"fmt"
	"regexp"
)

func main() {
	// Simulate what encoding/json emits for an int64 vs a rounded float64.
	intPath := fmt.Appendf(nil, `{"size_bytes":%d}`, int64(9007199254740993))
	floatPath := fmt.Appendf(nil, `{"size_bytes":%v}`, float64(9007199254740993))
	pat := regexp.MustCompile(`"([a-z_]+)":(-?[0-9]+)`)
	for _, b := range [][]byte{intPath, floatPath} {
		m := pat.FindSubmatch(b)
		fmt.Printf("body=%s captured=%s matches-want=%v\n", b, m[2], string(m[2]) == "9007199254740993")
	}
}
EOF
rm -f "$HOME/jsonprobe/main.go"; cd "$HOME/jsonprobe" && go run mut_test.go 2>&1; rm -f mut_test.go

gofmt -l internal/api/input_boundary_test.go && echo "MY-FILE-CLEAN"
cat > "$HOME/jsonprobe/mutcheck.go" <<'EOF'
package main
import ("fmt";"regexp")
func main() {
	intPath := fmt.Appendf(nil, `{"size_bytes":%d}`, int64(9007199254740993))
	floatPath := fmt.Appendf(nil, `{"size_bytes":%v}`, float64(9007199254740993))
	pat := regexp.MustCompile(`"([a-z_]+)":(-?[0-9]+)`)
	for _, b := range [][]byte{intPath, floatPath} {
		m := pat.FindSubmatch(b)
		fmt.Printf("body=%-34s captured=%s detects-rounding=%v\n", b, m[2], string(m[2]) != "9007199254740993")
	}
}
EOF
cd "$HOME/jsonprobe" && rm -f go.mod mut_test.go && go mod init jp >/dev/null 2>&1 && go run mutcheck.go 2>&1; rm -rf "$HOME/jsonprobe"

